"use strict";(globalThis.webpackChunkgrc||=[]).push([[3145],{87500(e){e.exports=JSON.parse('{"citeKey":"kougkas2016towardsenergy","slug":"kougkas-2016-towards-energy-6062","title":"Towards Energy Efficient Data Management in HPC: The Open Ethernet Drive Approach","authors":["A. Kougkas","A. Fleck","X.-H. Sun"],"venue":"PDSW-DISCS\'16, in conjunction with SC\'16","type":"Workshop","entryType":"inproceedings","date":"January, 2016","year":2016,"era":"iit","month":1,"doi":"10.1109/pdsw-discs.2016.012","abstract":"An Open Ethernet Drive (OED) is a new technology that encloses into a hard drive (HDD or SSD) a low-power processor, a fixed-size memory and an Ethernet card. In this study, we thoroughly evaluate the performance of such device and the energy requirements to operate it. The results show that first it is a viable solution to offload data-intensive computations on the OED while maintaining a reasonable performance, and second, the energy consumption savings from utilizing such technology are significant as it only consumes 10% of the power needed by a normal server node. We propose that by using OED devices as storage servers in HPC, we can run a reliable, scalable, cost and energy efficient storage solution.","hasAbstract":true,"lede":"We propose that by using OED devices as storage servers in HPC, we can run a reliable, scalable, cost and energy efficient storage solution.","links":{"pdf":"https://grc.iit.edu/papers/2016/kougkas-2016-towards-energy-6062.pdf","slides":"https://grc.iit.edu/papers/2016/kougkas-2016-towards-energy-6062-slides.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["wisio"],"memberAuthors":["kougkas-anthony","sun-xian-he"]}')}}]);